import java.util.Scanner;

public class BookFair {
    private String bname;
    private double price;

    public BookFair() {
        bname = "";
        price = 0.0;
    }

    public void input() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Book Title: ");
        bname = sc.nextLine();
        System.out.print("Enter Book Price: ");
        price = sc.nextDouble();
    }

    public void calculate() {
        double discountRate = 0.0;
        if (price <= 1000) {
            discountRate = 0.02;
        } else if (price <= 3000) {
            discountRate = 0.10;
        } else {
            discountRate = 0.15;
        }

        double discount = price * discountRate;
        double netPrice = price - discount;

        System.out.println("\n========================================");
        System.out.println("            BOOK FAIR INVOICE           ");
        System.out.println("========================================");
        System.out.println("Book Title     : " + bname);
        System.out.printf("Original Price : Rs. %.2f\n", price);
        System.out.printf("Discount       : Rs. %.2f (%.0f%%)\n", discount, (discountRate * 100));
        System.out.printf("Net Payable    : Rs. %.2f\n", netPrice);
        System.out.println("========================================");
    }

    public static void main(String[] args) {
        BookFair book = new BookFair();
        book.input();
        book.calculate();
    }
}
```

