import java.util.Scanner;

public class MatrixBoundaryElements {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] a = new int[3][3];

        System.out.println("Enter 9 elements for 3x3 Matrix:");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                System.out.print("a[" + i + "][" + j + "]: ");
                a[i][j] = sc.nextInt();
            }
        }

        System.out.println("\n--- Full Matrix ---");
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                System.out.print(a[i][j] + "\t");
            }
            System.out.println();
        }

        System.out.println("\n--- Boundary Elements ---");
        int boundarySum = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (i == 0 || i == 2 || j == 0 || j == 2) {
                    System.out.print(a[i][j] + "\t");
                    boundarySum += a[i][j];
                } else {
                    System.out.print("\t");
                }
            }
            System.out.println();
        }

        System.out.println("\nSum of Boundary Elements: " + boundarySum);
    }
}
```

