public class SeriesOverloading {
    public double series(double n) {
        double sum = 0.0;
        for (int i = 1; i <= n; i++) {
            sum += 1.0 / i;
        }
        return sum;
    }

    public double series(double a, double n) {
        double sum = 0.0;
        int num = 1;
        int power = 2;
        for (int i = 1; i <= n; i++) {
            sum += num / Math.pow(a, power);
            num += 3;
            power += 3;
        }
        return sum;
    }

    public double series() {
        double sum = 0.0;
        for (int i = 1; i <= 20; i++) {
            if (i % 2 == 1) sum += i;
            else sum -= i;
        }
        return sum;
    }

    public static void main(String[] args) {
        SeriesOverloading obj = new SeriesOverloading();
        System.out.printf("Series 1 (n=5)     : %.4f\n", obj.series(5.0));
        System.out.printf("Series 2 (a=2, n=4): %.4f\n", obj.series(2.0, 4.0));
        System.out.printf("Series 3 (to 20)   : %.0f\n", obj.series());
    }
}
```

